<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetCodeVO;

trait TemplateAssetCodeAccessor
{
    private TemplateAssetCodeVO $_code;
    public function getCode(): string
    {
        return $this->_code->value();
    }
    public function code(): TemplateAssetCodeVO
    {
        return $this->_code;
    }
    public function isCodeChanged(?self $original = null): bool
    {
        return !$this->_code->equals($original?->_code);
    }
    public function withCode(TemplateAssetCodeVO|string $code): self
    {
        $copy = clone $this;
        $copy->_code = TemplateAssetCodeVO::from($code);
        return $copy;
    }
}
